from pathlib import Path
import base64, shutil, sys

PROJECT = Path(r"C:\Users\Kane\Documents\Projects\Cylinder_Quote_To_HTML\Cylinder_Quote_Web_Milestone_1")
FILES = {'app/templates/index.html': '', 'app/static/app.js': '', 'app/catalog.py': ''}

def main():
    print("="*72)
    print("JIT CYLINDER QUOTE - ORDERENTRY FIELD ORDER PATCH")
    print("="*72)
    if not PROJECT.exists():
        print(f"ERROR: Installed project not found at {PROJECT}")
        print("Make sure Web Milestone 1 has been installed first.")
        input("Press Enter to close...")
        return 1
    for rel, encoded in FILES.items():
        target = PROJECT / rel
        if not target.exists():
            print(f"ERROR: Expected file not found: {target}")
            input("Press Enter to close...")
            return 1
        backup = target.with_suffix(target.suffix + ".before_order_patch")
        if not backup.exists():
            shutil.copy2(target, backup)
        target.write_bytes(base64.b64decode(encoded))
        print(f"Updated: {rel}")
    print()
    print("SUCCESS: Web form now follows the Excel OrderEntry/model-code sequence:")
    print("  Series -> Mount -> Bore -> Stroke -> Rod -> Rod Style -> Cushion -> Ports -> Seal -> DRE")
    print("  Discount and Rod Boot follow the cylinder-definition fields.")
    print()
    print("Stop the running server with Ctrl+C, restart RUN_CYLINDER_QUOTE.bat,")
    print("then refresh the browser (Ctrl+F5 if needed).")
    input("Press Enter to close...")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
